/** Silkscreen advances shared by web and headless hosts; generated by tools/fonts/metrics.py.
    Units are from the unmodified OFL font, not browser-dependent fallback fonts. */
import metrics from './font-metrics.json';

const advances: Readonly<Record<string, number>> = metrics.advances;

/** Screen2D supports regular Silkscreen at its two native pixel sizes. */
export function measurePixelText(text: string, font: string): { width: number } {
  const match = /^(8|16)px Silkscreen(?:,|$)/.exec(font);
  if (!match) throw new Error('Screen2D.font must be 8 or 16 px Silkscreen');
  let units = 0;
  // Canvas normalises ASCII whitespace to a space before measuring text.
  for (const char of text.replace(/[\t\n\f\r]/g, ' ')) {
    units += advances[String(char.codePointAt(0))] ?? metrics.missingAdvance;
  }
  return { width: units * Number(match[1]) / metrics.unitsPerEm };
}
